'use strict';
const H={};
const p={"left":1,"right":1.2,"dt":0.5};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 写清差速模型和单位
Object.assign(s, ((s,p)=>({track:.5,pose:[0,0,0]}))(s, p));
// 由轮速求机体速度
Object.assign(s, ((s,p)=>({v:(p.left+p.right)/2,omega:(p.right-p.left)/s.track}))(s, p));
// 积分一段恒定速度运动
Object.assign(s, ((s,p)=>{const a=s.omega*p.dt;return {next:Math.abs(s.omega)<1e-9?[s.v*p.dt,0,a]:[s.v/s.omega*Math.sin(a),s.v/s.omega*(1-Math.cos(a)),a]};})(s, p));
// 报告里程计的假设
Object.assign(s, ((s,p)=>({distance:s.v*p.dt,heading:s.next[2]}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={norm:xs=>{const z=xs.reduce((a,b)=>a+b,0);if(!(z>0))throw Error('归一化总量必须为正');return xs.map(x=>x/z);}};
const p={"range":2,"sigma":0.5};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 为两个位置预测测距
Object.assign(s, ((s,p)=>({positions:[2,3],predicted:[3,2]}))(s, p));
// 计算残差
Object.assign(s, ((s,p)=>({residuals:s.predicted.map(z=>p.range-z)}))(s, p));
// 计算高斯似然
Object.assign(s, ((s,p)=>({likelihoods:s.residuals.map(e=>Math.exp(-.5*(e/p.sigma)**2)/(p.sigma*Math.sqrt(2*Math.PI)))}))(s, p));
// 合并均匀先验
Object.assign(s, ((s,p)=>({posterior:H.norm(s.likelihoods)}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={sum:xs=>xs.reduce((a,b)=>a+b,0),
norm:xs=>{const z=xs.reduce((a,b)=>a+b,0);if(!(z>0))throw Error('归一化总量必须为正');return xs.map(x=>x/z);}};
const p={"sensor":0.8};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 先保存上一步信念
Object.assign(s, ((s,p)=>({prior:[.6,.4]}))(s, p));
// 先预测再观测
Object.assign(s, ((s,p)=>({predicted:[.75*s.prior[0]+.25*s.prior[1],.25*s.prior[0]+.75*s.prior[1]]}))(s, p));
// 乘入左侧观测似然
Object.assign(s, ((s,p)=>({unnormalized:[s.predicted[0]*p.sensor,s.predicted[1]*(1-p.sensor)]}))(s, p));
// 归一化得到后验
Object.assign(s, ((s,p)=>({evidence:H.sum(s.unnormalized),posterior:H.norm(s.unnormalized)}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={};
const p={"x":2,"variance":0.5,"noise":0.5};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 定义非线性传感器
Object.assign(s, ((s,p)=>({predicted:p.x*p.x,jacobian:2*p.x,measurement:5}))(s, p));
// 传播观测不确定性
Object.assign(s, ((s,p)=>({innovation:s.measurement-s.predicted,innovationVariance:s.jacobian*s.jacobian*p.variance+p.noise}))(s, p));
// 计算Kalman增益
Object.assign(s, ((s,p)=>({gain:p.variance*s.jacobian/s.innovationVariance}))(s, p));
// 修正均值与方差
Object.assign(s, ((s,p)=>({updated:p.x+s.gain*s.innovation,posteriorVariance:(1-s.gain*s.jacobian)**2*p.variance+s.gain*s.gain*p.noise}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={sum:xs=>xs.reduce((a,b)=>a+b,0),
norm:xs=>{const z=xs.reduce((a,b)=>a+b,0);if(!(z>0))throw Error('归一化总量必须为正');return xs.map(x=>x/z);}};
const p={"measurement":1,"sigma":0.5,"offset":0.1};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 准备四个等权粒子
Object.assign(s, ((s,p)=>({particles:[0,.5,1,2]}))(s, p));
// 按似然更新权重
Object.assign(s, ((s,p)=>({weights:H.norm(s.particles.map(x=>Math.exp(-.5*((p.measurement-x)/p.sigma)**2)))}))(s, p));
// 检查有效样本数
Object.assign(s, ((s,p)=>({ess:1/H.sum(s.weights.map(x=>x*x)),cdf:s.weights.map((_,i)=>H.sum(s.weights.slice(0,i+1)))}))(s, p));
// 系统重采样
Object.assign(s, ((s,p)=>({draws:[0,1,2,3].map(k=>p.offset+k/4),resampled:[0,1,2,3].map(k=>s.particles[s.cdf.findIndex(x=>p.offset+k/4<x)]),newWeights:[.25,.25,.25,.25]}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={};
const p={"occupied":0.75,"hits":2};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 从未知开始
Object.assign(s, ((s,p)=>({prior:.5,priorLogOdds:0}))(s, p));
// 把逆传感器概率转成对数几率
Object.assign(s, ((s,p)=>({increment:Math.log(p.occupied/(1-p.occupied))}))(s, p));
// 累积条件独立的命中
Object.assign(s, ((s,p)=>({history:Array.from({length:p.hits+1},(_,k)=>k*s.increment),logOdds:p.hits*s.increment}))(s, p));
// 还原概率
Object.assign(s, ((s,p)=>({probability:1/(1+Math.exp(-s.logOdds))}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={};
const p={"odom":1.2,"loop":2};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 固定第一帧消除自由漂移
Object.assign(s, ((s,p)=>({raw:[0,1,1+p.odom]}))(s, p));
// 列出正规方程
Object.assign(s, ((s,p)=>({rhs:[1-p.odom,p.odom+p.loop]}))(s, p));
// 解出最小二乘位姿
Object.assign(s, ((s,p)=>({poses:[0,(2*s.rhs[0]+s.rhs[1])/3,(s.rhs[0]+2*s.rhs[1])/3]}))(s, p));
// 回算全部残差
Object.assign(s, ((s,p)=>({residuals:[s.poses[1]-1,s.poses[2]-s.poses[1]-p.odom,s.poses[2]-p.loop]}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={};
const p={"weight":1};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 定义一个有限图
Object.assign(s, ((s,p)=>({names:['S','A','B','G'],edges:[[[1,1],[2,2]],[[3,4]],[[3,1]],[]],heuristic:[3,1,1,0]}))(s, p));
// 从起点执行带重新打开的A*
Object.assign(s, ((s,p)=>{const g=[0,Infinity,Infinity,Infinity],parent=[-1,-1,-1,-1],open=[0],expanded=[];while(open.length&&expanded.length<20){open.sort((a,b)=>(g[a]+p.weight*s.heuristic[a])-(g[b]+p.weight*s.heuristic[b]));const n=open.shift();expanded.push(n);if(n===3)break;for(const [to,c] of s.edges[n])if(g[n]+c<g[to]){g[to]=g[n]+c;parent[to]=n;if(!open.includes(to))open.push(to);}}return {costs:g.map(x=>Number.isFinite(x)?x:null),parent,expanded};})(s, p));
// 回溯到起点
Object.assign(s, ((s,p)=>{const path=[];if(s.expanded.includes(3)){for(let n=3;n!==-1;n=s.parent[n])path.unshift(s.names[n]);}return {path};})(s, p));
// 记录搜索代价和路径长度
Object.assign(s, ((s,p)=>({cost:s.costs[3],expandedCount:s.expanded.length}))(s, p));
console.log(JSON.stringify(s,null,2));
